<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Pastimes — Seller Requests</title><link rel="stylesheet" href="pastimes.css"></head><body><div class="layout"><?php renderSidebar('requests'); ?><main class="main"><div class="page-header"><div><h1 class="page-title">Seller Requests</h1><p class="page-sub">Approve or reject clothing submitted by sellers.</p></div></div><div class="card table-wrap"><table class="table"><tr><th>Image</th><th>Seller</th><th>Item</th><th>Price</th><th>Status</th><th>Action</th></tr><?php if($result->num_rows==0): ?><tr><td colspan="6" class="muted">No seller requests found.</td></tr><?php endif; while($row=$result->fetch_assoc()): ?><tr><td><img class="thumb" src="<?php echo e($row['image']); ?>"></td><td><?php echo e($row['sellerName']); ?><br><span class="muted"><?php echo e($row['sellerEmail']); ?></span></td><td><strong><?php echo e($row['brand']); ?></strong><br><span class="muted"><?php echo e($row['description']); ?> · Size <?php echo e($row['size']); ?></span></td><td><?php echo money($row['price']); ?></td><td><span class="pill <?php echo e($row['status']); ?>"><?php echo e($row['status']); ?></span></td><td class="actions"><?php if($row['status']=='pending'): ?><a class="btn btn-success" href="approveRequest.php?id=<?php echo $row['requestID']; ?>&action=approve">Approve</a><a class="btn btn-danger" href="approveRequest.php?id=<?php echo $row['requestID']; ?>&action=reject">Reject</a><?php else: ?><span class="muted">Reviewed</span><?php endif; ?></td></tr><?php endwhile; ?></table></div></main></div></body></html>
